import axios, { AxiosInstance } from 'axios';

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8000';

export interface Source {
  episode_title: string;
  guest?: string;
  excerpt: string;
  chunk_id: string;
  source_file: string;
}

export interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  sources?: Source[];
  created_at: string;
  metadata?: {
    model_provider?: string;
    model_name?: string;
    retrieval_count?: number;
    generation_time_ms?: number;
  };
}

export interface Session {
  id: string;
  created_at: string;
  updated_at: string;
  title?: string;
  message_count?: number;
  messages?: Message[];
}

export interface Artifact {
  id: string;
  session_id: string;
  message_id?: string;
  type: 'markdown' | 'html' | 'css';
  content: string;
  created_at: string;
  metadata?: {
    title?: string;
    description?: string;
    size_bytes?: number;
  };
}

export interface CreateMessageRequest {
  content: string;
  model_provider?: string;
}

export interface CreateMessageResponse extends Message {}

export interface HealthResponse {
  status: string;
  database?: string;
  ollama?: string;
  timestamp: string;
  service?: string;
  version?: string;
}

export class ApiClient {
  private client: AxiosInstance;

  constructor(baseURL: string = API_URL) {
    this.client = axios.create({
      baseURL: `${baseURL}/api`,
      headers: {
        'Content-Type': 'application/json',
      },
      timeout: 120000, // 2 minutes for LLM responses
    });
  }

  // Health
  async checkHealth(): Promise<HealthResponse> {
    const response = await this.client.get<HealthResponse>('/health');
    return response.data;
  }

  // Sessions
  async createSession(): Promise<Session> {
    const response = await this.client.post<Session>('/sessions');
    return response.data;
  }

  async listSessions(limit = 50, offset = 0): Promise<{ sessions: Session[]; total: number }> {
    const response = await this.client.get<{ sessions: Session[]; total: number; limit: number; offset: number }>(
      '/sessions',
      { params: { limit, offset } }
    );
    return response.data;
  }

  async getSession(sessionId: string): Promise<Session> {
    const response = await this.client.get<Session>(`/sessions/${sessionId}`);
    return response.data;
  }

  // Messages
  async sendMessage(sessionId: string, request: CreateMessageRequest): Promise<CreateMessageResponse> {
    const response = await this.client.post<CreateMessageResponse>(
      `/sessions/${sessionId}/messages`,
      request
    );
    return response.data;
  }

  // Artifacts
  async getArtifact(artifactId: string): Promise<Artifact> {
    const response = await this.client.get<Artifact>(`/artifacts/${artifactId}`);
    return response.data;
  }

  async listArtifacts(sessionId: string): Promise<Artifact[]> {
    const response = await this.client.get<Artifact[]>(`/sessions/${sessionId}/artifacts`);
    return response.data;
  }
}

export const apiClient = new ApiClient();

import React, { createContext, useContext, useState, useCallback, ReactNode } from 'react';
import { Session, Artifact } from '../lib/api';

interface AppContextType {
  currentSession: Session | null;
  setCurrentSession: (session: Session | null) => void;
  sessions: Session[];
  setSessions: (sessions: Session[]) => void;
  currentArtifact: Artifact | null;
  setCurrentArtifact: (artifact: Artifact | null) => void;
  isArtifactViewerOpen: boolean;
  openArtifactViewer: (artifact: Artifact) => void;
  closeArtifactViewer: () => void;
  isSidebarOpen: boolean;
  toggleSidebar: () => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [currentSession, setCurrentSession] = useState<Session | null>(null);
  const [sessions, setSessions] = useState<Session[]>([]);
  const [currentArtifact, setCurrentArtifact] = useState<Artifact | null>(null);
  const [isArtifactViewerOpen, setIsArtifactViewerOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  const openArtifactViewer = useCallback((artifact: Artifact) => {
    setCurrentArtifact(artifact);
    setIsArtifactViewerOpen(true);
  }, []);

  const closeArtifactViewer = useCallback(() => {
    setIsArtifactViewerOpen(false);
    // Keep artifact for a moment to allow smooth close animation
    setTimeout(() => setCurrentArtifact(null), 300);
  }, []);

  const toggleSidebar = useCallback(() => {
    setIsSidebarOpen(prev => !prev);
  }, []);

  return (
    <AppContext.Provider
      value={{
        currentSession,
        setCurrentSession,
        sessions,
        setSessions,
        currentArtifact,
        setCurrentArtifact,
        isArtifactViewerOpen,
        openArtifactViewer,
        closeArtifactViewer,
        isSidebarOpen,
        toggleSidebar,
      }}
    >
      {children}
    </AppContext.Provider>
  );
};

export const useApp = (): AppContextType => {
  const context = useContext(AppContext);
  if (!context) {
    throw new Error('useApp must be used within AppProvider');
  }
  return context;
};

import React, { ButtonHTMLAttributes } from 'react';

interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost';
  size?: 'sm' | 'md' | 'lg';
  children: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({
  variant = 'primary',
  size = 'md',
  className = '',
  children,
  disabled,
  ...props
}) => {
  const baseStyles = 'font-medium rounded-md transition-all duration-150 focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed';

  const variantStyles = {
    primary: 'bg-primary text-white hover:bg-primary-hover focus-visible:ring-primary',
    secondary: 'bg-transparent text-text-primary border border-border-primary hover:bg-surface-hover focus-visible:ring-border-focus',
    ghost: 'bg-transparent text-text-secondary hover:bg-bg-tertiary focus-visible:ring-border-focus',
  };

  const sizeStyles = {
    sm: 'px-3 py-1.5 text-sm',
    md: 'px-5 py-2.5 text-body',
    lg: 'px-6 py-3 text-lg',
  };

  return (
    <button
      className={`${baseStyles} ${variantStyles[variant]} ${sizeStyles[size]} ${className}`}
      disabled={disabled}
      {...props}
    >
      {children}
    </button>
  );
};

import React, { InputHTMLAttributes, forwardRef } from 'react';

interface InputProps extends InputHTMLAttributes<HTMLInputElement> {
  label?: string;
  error?: string;
}

export const Input = forwardRef<HTMLInputElement, InputProps>(
  ({ label, error, className = '', ...props }, ref) => {
    return (
      <div className="w-full">
        {label && (
          <label className="block text-sm font-medium text-text-primary mb-2">
            {label}
          </label>
        )}
        <input
          ref={ref}
          className={`
            w-full bg-bg-primary border-2 border-border-primary rounded-md
            px-4 py-3 text-body text-text-primary
            transition-colors duration-150
            placeholder:text-text-tertiary
            focus:outline-none focus:border-border-focus focus:ring-4 focus:ring-blue-50
            disabled:opacity-50 disabled:cursor-not-allowed
            ${error ? 'border-red-500 focus:border-red-500 focus:ring-red-50' : ''}
            ${className}
          `}
          {...props}
        />
        {error && (
          <p className="mt-1 text-sm text-red-600">{error}</p>
        )}
      </div>
    );
  }
);

Input.displayName = 'Input';

import React, { HTMLAttributes } from 'react';

interface CardProps extends HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode;
  hover?: boolean;
}

export const Card: React.FC<CardProps> = ({
  children,
  hover = false,
  className = '',
  ...props
}) => {
  return (
    <div
      className={`
        bg-surface-base border border-border-primary rounded-lg p-6
        shadow-sm
        ${hover ? 'hover:border-border-focus hover:shadow-md transition-all duration-200 cursor-pointer' : ''}
        ${className}
      `}
      {...props}
    >
      {children}
    </div>
  );
};

import React from 'react';

interface LoadingSpinnerProps {
  size?: 'sm' | 'md' | 'lg';
  className?: string;
}

export const LoadingSpinner: React.FC<LoadingSpinnerProps> = ({ size = 'md', className = '' }) => {
  const sizeStyles = {
    sm: 'w-4 h-4',
    md: 'w-6 h-6',
    lg: 'w-8 h-8',
  };

  return (
    <div className={`inline-block ${sizeStyles[size]} ${className}`}>
      <div className="w-full h-full border-3 border-primary border-t-transparent rounded-full animate-spin"></div>
    </div>
  );
};

export const LoadingDots: React.FC<{ className?: string }> = ({ className = '' }) => {
  return (
    <div className={`flex space-x-1 ${className}`}>
      <div className="w-2 h-2 bg-text-tertiary rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
      <div className="w-2 h-2 bg-text-tertiary rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
      <div className="w-2 h-2 bg-text-tertiary rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
    </div>
  );
};

import React from 'react';
import ReactMarkdown from 'react-markdown';
import { Message } from '../lib/api';
import { SourceCard } from './SourceCard';
import { formatDistanceToNow } from 'date-fns';

interface MessageBubbleProps {
  message: Message;
}

export const MessageBubble: React.FC<MessageBubbleProps> = ({ message }) => {
  const isUser = message.role === 'user';
  const timestamp = formatDistanceToNow(new Date(message.created_at), { addSuffix: true });

  if (isUser) {
    return (
      <div className="flex justify-end mb-6">
        <div className="max-w-[680px] bg-bg-tertiary rounded-lg px-6 py-4">
          <div className="text-text-primary whitespace-pre-wrap">{message.content}</div>
          <div className="text-text-tertiary text-xs mt-2 text-right">{timestamp}</div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex justify-start mb-8">
      <div className="max-w-[680px] w-full">
        <div className="flex items-start space-x-3">
          <div className="flex-shrink-0 w-8 h-8 bg-primary rounded-full flex items-center justify-center text-white font-semibold text-sm mt-1">
            L
          </div>
          <div className="flex-1 bg-ai-bg border border-ai-border rounded-lg px-6 py-4">
            <div className="prose prose-sm max-w-none text-text-primary">
              <ReactMarkdown
                components={{
                  p: ({ children }) => <p className="mb-4 last:mb-0">{children}</p>,
                  strong: ({ children }) => <strong className="font-semibold text-text-primary">{children}</strong>,
                  ul: ({ children }) => <ul className="list-disc pl-5 mb-4 space-y-1">{children}</ul>,
                  ol: ({ children }) => <ol className="list-decimal pl-5 mb-4 space-y-1">{children}</ol>,
                  li: ({ children }) => <li className="text-text-primary">{children}</li>,
                  h1: ({ children }) => <h1 className="text-xl font-semibold mb-3 mt-4 first:mt-0">{children}</h1>,
                  h2: ({ children }) => <h2 className="text-lg font-semibold mb-2 mt-3 first:mt-0">{children}</h2>,
                  h3: ({ children }) => <h3 className="text-base font-semibold mb-2 mt-3 first:mt-0">{children}</h3>,
                  code: ({ children }) => (
                    <code className="bg-bg-tertiary px-1.5 py-0.5 rounded text-sm font-mono">{children}</code>
                  ),
                  pre: ({ children }) => (
                    <pre className="bg-bg-tertiary p-4 rounded-md overflow-x-auto mb-4">
                      {children}
                    </pre>
                  ),
                }}
              >
                {message.content}
              </ReactMarkdown>
            </div>

            {message.sources && message.sources.length > 0 && (
              <div className="mt-6 pt-4 border-t border-ai-border">
                <div className="text-sm font-medium text-text-secondary mb-3">
                  Sources ({message.sources.length})
                </div>
                <div className="space-y-2">
                  {message.sources.map((source, idx) => (
                    <SourceCard key={`${source.chunk_id}-${idx}`} source={source} />
                  ))}
                </div>
              </div>
            )}

            <div className="flex justify-between items-center mt-4 text-xs text-text-tertiary">
              <div>
                {message.metadata?.model_provider && message.metadata?.model_name && (
                  <span>
                    {message.metadata.model_provider} · {message.metadata.model_name}
                  </span>
                )}
              </div>
              <div>{timestamp}</div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Source } from '../lib/api';

interface SourceCardProps {
  source: Source;
}

export const SourceCard: React.FC<SourceCardProps> = ({ source }) => {
  return (
    <div className="bg-source-bg border border-source-border rounded-md p-3 hover:shadow-sm transition-shadow">
      <div className="flex items-start space-x-2">
        <span className="text-lg flex-shrink-0">📄</span>
        <div className="flex-1 min-w-0">
          <div className="font-medium text-source-text text-sm">
            {source.episode_title}
            {source.guest && <span className="font-normal"> · {source.guest}</span>}
          </div>
          {source.excerpt && (
            <p className="text-sm text-source-text mt-1.5 italic line-clamp-3">
              "{source.excerpt}"
            </p>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect, KeyboardEvent } from 'react';
import { Button } from './Button';

interface MessageComposerProps {
  onSend: (content: string) => void;
  disabled?: boolean;
  placeholder?: string;
}

export const MessageComposer: React.FC<MessageComposerProps> = ({
  onSend,
  disabled = false,
  placeholder = 'Type your question...',
}) => {
  const [content, setContent] = useState('');
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  const handleSend = () => {
    if (content.trim() && !disabled) {
      onSend(content.trim());
      setContent('');
      // Reset textarea height
      if (textareaRef.current) {
        textareaRef.current.style.height = 'auto';
      }
    }
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      e.preventDefault();
      handleSend();
    }
  };

  // Auto-resize textarea
  useEffect(() => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.min(textarea.scrollHeight, 200)}px`;
    }
  }, [content]);

  return (
    <div className="border-t border-border-primary bg-surface-base">
      <div className="max-w-4xl mx-auto p-4">
        <div className="flex items-end space-x-3">
          <div className="flex-1">
            <textarea
              ref={textareaRef}
              value={content}
              onChange={(e) => setContent(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder={placeholder}
              disabled={disabled}
              rows={1}
              className="
                w-full bg-bg-primary border-2 border-border-primary rounded-md
                px-4 py-3 text-body text-text-primary resize-none
                transition-colors duration-150
                placeholder:text-text-tertiary
                focus:outline-none focus:border-border-focus focus:ring-4 focus:ring-blue-50
                disabled:opacity-50 disabled:cursor-not-allowed
              "
              aria-label="Message input"
            />
            <div className="text-xs text-text-tertiary mt-1.5">
              Press ⌘+Enter to send
            </div>
          </div>
          <Button
            onClick={handleSend}
            disabled={disabled || !content.trim()}
            className="flex-shrink-0"
          >
            Send
          </Button>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect } from 'react';
import { useApp } from '../contexts/AppContext';
import { Button } from './Button';
import { apiClient, Session } from '../lib/api';
import { formatDistanceToNow } from 'date-fns';

export const SessionSidebar: React.FC = () => {
  const { currentSession, setCurrentSession, sessions, setSessions } = useApp();

  useEffect(() => {
    loadSessions();
  }, []);

  const loadSessions = async () => {
    try {
      const data = await apiClient.listSessions();
      setSessions(data.sessions);
    } catch (error) {
      console.error('Failed to load sessions:', error);
    }
  };

  const handleNewChat = async () => {
    try {
      const newSession = await apiClient.createSession();
      setSessions([newSession, ...sessions]);
      setCurrentSession(newSession);
    } catch (error) {
      console.error('Failed to create session:', error);
    }
  };

  const handleSelectSession = async (session: Session) => {
    try {
      const fullSession = await apiClient.getSession(session.id);
      setCurrentSession(fullSession);
    } catch (error) {
      console.error('Failed to load session:', error);
    }
  };

  const groupSessionsByTime = (sessions: Session[]) => {
    const now = new Date();
    const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
    const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

    return {
      today: sessions.filter(s => new Date(s.updated_at) > oneDayAgo),
      yesterday: sessions.filter(s => {
        const date = new Date(s.updated_at);
        return date <= oneDayAgo && date > sevenDaysAgo;
      }),
      older: sessions.filter(s => new Date(s.updated_at) <= sevenDaysAgo),
    };
  };

  const grouped = groupSessionsByTime(sessions);

  return (
    <div className="w-[280px] bg-bg-secondary border-r border-border-primary h-screen flex flex-col">
      <div className="p-4 border-b border-border-secondary">
        <Button
          onClick={handleNewChat}
          variant="primary"
          className="w-full"
        >
          + New Chat
        </Button>
      </div>

      <div className="flex-1 overflow-y-auto">
        {sessions.length === 0 ? (
          <div className="p-4 text-center text-text-tertiary text-sm">
            <div className="text-2xl mb-2">📚</div>
            <div>No conversations yet</div>
            <div className="mt-1">Click "New Chat" to start</div>
          </div>
        ) : (
          <div className="p-2">
            {grouped.today.length > 0 && (
              <SessionGroup
                title="Today"
                sessions={grouped.today}
                currentSessionId={currentSession?.id}
                onSelect={handleSelectSession}
              />
            )}
            {grouped.yesterday.length > 0 && (
              <SessionGroup
                title="Last 7 Days"
                sessions={grouped.yesterday}
                currentSessionId={currentSession?.id}
                onSelect={handleSelectSession}
              />
            )}
            {grouped.older.length > 0 && (
              <SessionGroup
                title="Older"
                sessions={grouped.older}
                currentSessionId={currentSession?.id}
                onSelect={handleSelectSession}
              />
            )}
          </div>
        )}
      </div>
    </div>
  );
};

interface SessionGroupProps {
  title: string;
  sessions: Session[];
  currentSessionId?: string;
  onSelect: (session: Session) => void;
}

const SessionGroup: React.FC<SessionGroupProps> = ({ title, sessions, currentSessionId, onSelect }) => {
  return (
    <div className="mb-4">
      <div className="text-xs font-semibold text-text-tertiary uppercase tracking-wider px-3 py-2">
        {title}
      </div>
      <div className="space-y-1">
        {sessions.map(session => (
          <button
            key={session.id}
            onClick={() => onSelect(session)}
            className={`
              w-full text-left px-3 py-2.5 rounded-md transition-colors
              ${currentSessionId === session.id
                ? 'bg-primary text-white'
                : 'text-text-primary hover:bg-surface-hover'
              }
            `}
          >
            <div className="font-medium text-sm truncate">
              {session.title || 'New conversation'}
            </div>
            <div className={`text-xs mt-0.5 ${currentSessionId === session.id ? 'text-blue-100' : 'text-text-tertiary'}`}>
              {session.message_count || 0} messages · {formatDistanceToNow(new Date(session.updated_at), { addSuffix: true })}
            </div>
          </button>
        ))}
      </div>
    </div>
  );
};

