import React, { useState, useEffect, useRef } from 'react';
import { useApp } from '../contexts/AppContext';
import { apiClient, Message } from '../lib/api';
import { EmptyState } from './EmptyState';
import { MessageBubble } from './MessageBubble';
import { MessageComposer } from './MessageComposer';
import { LoadingMessage } from './LoadingMessage';
import { ErrorMessage } from './ErrorMessage';

export const ConversationArea: React.FC = () => {
  const { currentSession, setCurrentSession, sessions, setSessions } = useApp();
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (currentSession?.messages) {
      setMessages(currentSession.messages);
    } else {
      setMessages([]);
    }
    setError(null);
  }, [currentSession]);

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSendMessage = async (content: string) => {
    if (!currentSession) {
      // Create new session if none exists
      try {
        const newSession = await apiClient.createSession();
        setCurrentSession(newSession);
        setSessions([newSession, ...sessions]);
        // Continue with sending the message
        await sendMessageToSession(newSession.id, content);
      } catch (err) {
        setError('Failed to create session. Please try again.');
        console.error(err);
      }
      return;
    }

    await sendMessageToSession(currentSession.id, content);
  };

  const sendMessageToSession = async (sessionId: string, content: string) => {
    setIsLoading(true);
    setError(null);

    // Add user message optimistically
    const userMessage: Message = {
      id: `temp-${Date.now()}`,
      role: 'user',
      content,
      created_at: new Date().toISOString(),
    };
    setMessages(prev => [...prev, userMessage]);

    try {
      const response = await apiClient.sendMessage(sessionId, {
        content,
        model_provider: 'ollama', // Can be made configurable
      });

      // Replace temp user message and add assistant response
      setMessages(prev => {
        const withoutTemp = prev.filter(m => m.id !== userMessage.id);
        return [...withoutTemp, { ...userMessage, id: response.id }, response];
      });

      // Update session title if this is the first message
      if (messages.length === 0 && currentSession) {
        const title = content.slice(0, 60) + (content.length > 60 ? '...' : '');
        const updatedSession = { ...currentSession, title, message_count: 2 };
        setCurrentSession(updatedSession);
        setSessions(prev =>
          prev.map(s => (s.id === sessionId ? updatedSession : s))
        );
      }
    } catch (err: any) {
      setError(
        err.response?.data?.message ||
        'Failed to send message. Please check that the backend and Ollama are running.'
      );
      // Remove the optimistic user message on error
      setMessages(prev => prev.filter(m => m.id !== userMessage.id));
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleExampleClick = (prompt: string) => {
    handleSendMessage(prompt);
  };

  const handleRetry = () => {
    setError(null);
    // Could implement retry logic here
  };

  if (!currentSession) {
    return (
      <div className="flex-1 flex flex-col h-screen">
        <EmptyState onExampleClick={handleExampleClick} />
        <MessageComposer onSend={handleSendMessage} disabled={isLoading} />
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col h-screen">
      <div className="flex-1 overflow-y-auto">
        <div className="max-w-4xl mx-auto p-6">
          {messages.length === 0 && !isLoading ? (
            <EmptyState onExampleClick={handleExampleClick} />
          ) : (
            <>
              {messages.map(message => (
                <MessageBubble key={message.id} message={message} />
              ))}
              {isLoading && <LoadingMessage stage="Searching Lenny's transcripts..." />}
              {error && <ErrorMessage message={error} onRetry={handleRetry} />}
              <div ref={messagesEndRef} />
            </>
          )}
        </div>
      </div>
      <MessageComposer onSend={handleSendMessage} disabled={isLoading} />
    </div>
  );
};

import React from 'react';
import { QueryClient, QueryClientProvider } from 'react-query';
import { AppProvider, useApp } from './contexts/AppContext';
import { SessionSidebar } from './components/SessionSidebar';
import { ConversationArea } from './components/ConversationArea';
import { ArtifactViewer } from './components/ArtifactViewer';

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      refetchOnWindowFocus: false,
      retry: 1,
    },
  },
});

function AppContent() {
  const { isArtifactViewerOpen } = useApp();

  return (
    <div className="flex h-screen bg-bg-primary overflow-hidden">
      <SessionSidebar />
      <ConversationArea />
      {isArtifactViewerOpen && <ArtifactViewer />}
    </div>
  );
}

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <AppProvider>
        <AppContent />
      </AppProvider>
    </QueryClientProvider>
  );
}

export default App;

